import{_ as e,o,c as a,ah as n}from"./chunks/framework.BVKoBI-M.js";const i="/projects/AiNovaRobot/en/latest/assets/image1.DQB4ZAwG.webp",g=JSON.parse('{"title":"4. Game Introduction and Notice","description":"","frontmatter":{},"headers":[],"relativePath":"docs/4.Game_Instruction.md","filePath":"docs/4.Game_Instruction.md"}'),r={name:"docs/4.Game_Instruction.md"};function c(s,t,l,d,m,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="_4-game-introduction-and-notice" tabindex="-1">4. Game Introduction and Notice <a class="header-anchor" href="#_4-game-introduction-and-notice" aria-label="Permalink to &quot;4. Game Introduction and Notice&quot;">​</a></h1><h2 id="_4-1-game-introduction" tabindex="-1">4.1 Game Introduction <a class="header-anchor" href="#_4-1-game-introduction" aria-label="Permalink to &quot;4.1 Game Introduction&quot;">​</a></h2><p>Mini AI autonomous driving kit is an AI self-driving traffic system combing AiNova robot and smart traffic scenarios. AiNova can execute visual analysis and judgment thorough WonderCam AI vision module to carry out road sign recognition and traffic light recognition.</p><p>This kit aims to provide student a platform to understand the fundamentals and major algorithms in the field of artificial intelligent and to learn the application projects of AI technologies. Machine learning, natural speech processing, computer vision, customization image recognition and other AI technologies which are used to simulate and solve real-life problems.</p><p>Mini intelligent transportation is applicable to AI learning class, extracurricular expansion, subject challenge and innovation competition. Intelligent transportation teaching platform helps student learn AI autonomous driving, smart city transport system, machine programming and electronic knowledge.</p><h2 id="_4-2-map-placement" tabindex="-1">4.2 Map Placement <a class="header-anchor" href="#_4-2-map-placement" aria-label="Permalink to &quot;4.2 Map Placement&quot;">​</a></h2><p>Please place the map correctly according to the content in “<strong>Lesson 1 Map Placement</strong>”.</p><h2 id="_4-3-notice" tabindex="-1">4.3 Notice <a class="header-anchor" href="#_4-3-notice" aria-label="Permalink to &quot;4.3 Notice&quot;">​</a></h2><ol><li>Due the program setting, AiNova must be placed in the area framed in following red box as the starting point.</li></ol><img loading="lazy" height="399" width="600" src="'+i+'" style="width:800px;" class="common_img"><ol start="2"><li><p>If the effect of line following is not good enough, you can adjust the sensitivity of line following senor. The debugging method is located in folder “<strong>6.Appendix/5.Debugging Instruction</strong>”. (please debug the sensitivity on white line.)</p></li><li><p>Manually change the turning direction of road sign.</p></li></ol><h2 id="_4-4-project-outcome" tabindex="-1">4.4 Project Outcome <a class="header-anchor" href="#_4-4-project-outcome" aria-label="Permalink to &quot;4.4 Project Outcome&quot;">​</a></h2><p>After placing map and other accessories according to “<strong>Lesson 1 Map Placement</strong>”, switch on the controller of traffic light and AiNova. Then, AiNova can perform road sign recognition, traffic light recognition and move repeatedly.</p>',13)])])}const u=e(r,[["render",c]]);export{g as __pageData,u as default};
